on jump01 'curl -fsS -m 3 http://web01.kestrel.internal/ >/dev/null' || fail "http on web01 doesn't work from the office anymore"
on app01 'curl -fsS -m 3 http://10.10.2.10/ >/dev/null' || fail "http to web01 from the backend net is blocked — 80 should be open to everyone"
on jump01 'curl -ksS -m 3 https://web01.kestrel.internal/ >/dev/null' || fail "https (443) on web01 is blocked"
as_user jump01 dhan 'ssh -o BatchMode=yes -o ConnectTimeout=3 web01 true' >/dev/null 2>&1 || fail "ssh from the office (jump01) to web01 is blocked — you locked us out 😬"
on app01 'nc -z -w 2 10.10.2.10 22' && fail "ssh on web01 is still reachable from the backend net (10.10.3.0/24)"
on jump01 'nc -z -w 2 10.10.2.10 8081' && fail "port 8081 (that debug server) is still reachable — everything else should be dropped"
on jump01 'curl -fsS -m 4 http://web01.kestrel.internal/api/health >/dev/null' || fail "web01 can't reach the API on app01 anymore (/api/ is broken) — are replies to its own outbound connections allowed?"
on web01 'getent hosts app01.kestrel.internal >/dev/null' || fail "web01 can't resolve DNS anymore"
on web01 'nft list chain inet filter input 2>/dev/null | grep -q "policy drop"' || on web01 'nft list ruleset | grep -q "hook input.*policy drop"' || fail "the input chain doesn't default to drop"
on web01 'systemctl is-enabled -q nftables && grep -q "hook input" /etc/nftables.conf && nft -c -f /etc/nftables.conf' >/dev/null 2>&1 || fail "rules are live but won't survive a reboot (/etc/nftables.conf + nftables.service enabled)"
